class Doc:
    def __init__(self, t):
        self.t = t

    def rep(self, old, new):
        n = self.t.count(old)
        assert n == 1, ('元の文の数が 1 でない', n, old[:70])
        self.t = self.t.replace(old, new)

    def _line(self, prefix):
        L = self.t.split(NL)
        idx = [i for i, l in enumerate(L) if l.startswith(prefix)]
        assert len(idx) == 1, ('行の頭の数が 1 でない', len(idx), prefix[:70])
        return L, idx[0]

    def rep_line(self, prefix, new_lines, span=1, expect_next=()):
        L, i = self._line(prefix)
        for k, p in enumerate(expect_next, 1):
            assert L[i + k].startswith(p), ('続きの行が合わない', k, L[i + k][:50])
        L[i:i + span] = new_lines if isinstance(new_lines, list) else [new_lines]
        self.t = NL.join(L)

    def after_line(self, prefix, new_lines):
        L, i = self._line(prefix)
        L[i + 1:i + 1] = new_lines if isinstance(new_lines, list) else [new_lines]
        self.t = NL.join(L)


